import { describe, it, expect } from 'vitest'
import {
  statPointCap,
  ensureStatPoints,
  grantLevelStatPoints,
  addAllocation,
  trainCostPerPoint,
  trainPlayer,
  applyLevelUps,
  getRankForLevel,
  getNextRank,
  getXpProgress,
  type ProgressPlayer,
} from '../src/engine/progression'
import { getTotalStats } from '../src/engine/stats'
import { levelsData, ranks } from '../src/data'

// Parity fixtures generated by RUNNING the bot's stat-progression.js,
// rank-engine.js and combat-engine.js applyLevelUps().

function makePlayer(
  classId = 'warrior',
  raceId = 'human',
): ProgressPlayer {
  const t = getTotalStats(classId, raceId, 1)
  return {
    name: 'Tester',
    level: 1,
    xp: 0,
    classId,
    raceId,
    hp: t.maxHp,
    maxHp: t.maxHp,
    mp: t.maxMp,
    maxMp: t.maxMp,
    stats: { str: t.str, agi: t.agi, int: t.int, def: t.def, lck: t.lck },
    baseStats: {
      str: t.str, agi: t.agi, int: t.int, def: t.def, lck: t.lck,
      maxHp: t.maxHp, maxMp: t.maxMp,
    },
    statPoints: {
      version: 2,
      earned: 15,
      spent: 0,
      unallocated: 15,
      allocations: { str: 0, agi: 0, int: 0, def: 0, lck: 0 },
    },
    wallet: { solars: 1000, gems: 0 },
  }
}

describe('levels data sanity', () => {
  it('cap 100, 15 points/level, 1500 max, xpTable covers 2..200', () => {
    expect(levelsData.levelCap).toBe(100)
    expect(levelsData.statPointsPerLevel).toBe(15)
    expect(levelsData.maxStatPoints).toBe(1500)
    expect(levelsData.xpTable['2']).toBe(348)
    expect(levelsData.xpTable['200']).toBe(1386290)
    for (let l = 2; l <= 200; l++) {
      expect(typeof levelsData.xpTable[String(l)]).toBe('number')
    }
  })

  it('growth and training constants (bot parity)', () => {
    expect(levelsData.statGrowthPerLevel).toEqual({
      primaryStat: 2, secondaryStat: 0, maxHp: 10, maxMp: 5,
    })
    expect(levelsData.statTraining).toEqual({
      baseCostPerPoint: 100, costPerLevel: 25, defaultPoints: 15,
    })
  })
})

describe('statPointCap / trainCostPerPoint (bot parity)', () => {
  it.each([
    [1, 15],
    [10, 150],
    [100, 1500],
  ])('cap at level %i = %i', (level, cap) => {
    expect(statPointCap(level)).toBe(cap)
  })

  it.each([
    [1, 125],
    [10, 350],
    [100, 2600],
  ])('train cost at level %i = %i', (level, cost) => {
    expect(trainCostPerPoint(level)).toBe(cost)
  })
})

describe('stat allocation', () => {
  it('spends unallocated points into baseStats and stats', () => {
    const p = makePlayer()
    const r = addAllocation(p, 'str', 5)
    expect(r.ok).toBe(true)
    expect(p.stats.str).toBe(15) // 10 + 5
    expect(p.baseStats.str).toBe(15)
    expect(p.statPoints.unallocated).toBe(10)
    expect(p.statPoints.spent).toBe(5)
    expect(p.statPoints.allocations.str).toBe(5)
  })

  it('refuses over-spend and invalid stats', () => {
    const p = makePlayer()
    expect(addAllocation(p, 'str', 99)).toMatchObject({ ok: false, error: 'not_enough', available: 15 })
    expect(addAllocation(p, 'hp', 1)).toMatchObject({ ok: false, error: 'invalid' })
    expect(addAllocation(p, 'str', 0)).toMatchObject({ ok: false, error: 'invalid' })
  })

  it('ensureStatPoints keeps an already-v2 save untouched', () => {
    const p = makePlayer()
    const before = p.statPoints
    expect(ensureStatPoints(p)).toBe(before)
  })
})

describe('grantLevelStatPoints', () => {
  it('grants 15 per level up to the cap', () => {
    const p = makePlayer()
    expect(grantLevelStatPoints(p, 1, 2)).toBe(15)
    expect(p.statPoints.earned).toBe(30)
    expect(p.statPoints.unallocated).toBe(30)
  })
})

describe('trainPlayer (bot parity)', () => {
  // Verified against the bot: a fresh level-1 save has already earned the
  // full level-1 pool (15/15), so training reads 'full' — same as
  // lib/stat-progression.js. Buying happens only when earned < cap (e.g. a
  // partially earned pool).
  it('fresh level-1 save is already at its cap → full', () => {
    const p = makePlayer()
    p.wallet.solars = 10_000
    expect(trainPlayer(p, 4)).toMatchObject({ ok: false, error: 'full', cap: 15 })
    expect(p.wallet.solars).toBe(10_000)
  })

  it('buys points with solars at the level price when there is room', () => {
    const p = makePlayer()
    p.wallet.solars = 10_000
    p.statPoints.earned = 0 // partially earned pool → room to buy
    const r = trainPlayer(p, 4)
    expect(r).toMatchObject({ ok: true, points: 4, cost: 500 }) // 4 × 125
    expect(p.wallet.solars).toBe(9500)
    expect(p.statPoints.unallocated).toBe(19) // 15 + 4
  })

  it('fails when poor', () => {
    const p = makePlayer()
    p.wallet.solars = 10
    p.statPoints.earned = 0
    expect(trainPlayer(p, 1)).toMatchObject({ ok: false, error: 'poor', cost: 125, have: 10 })
    expect(p.wallet.solars).toBe(10)
  })

  it('rejects non-positive amounts', () => {
    const p = makePlayer()
    expect(trainPlayer(p, 0)).toMatchObject({ ok: false, error: 'invalid' })
    expect(trainPlayer(p, -3)).toMatchObject({ ok: false, error: 'invalid' })
  })
})

describe('applyLevelUps (bot parity)', () => {
  it('levels at xp >= xpTable[2] with correct stat growth and full heal', () => {
    const p = makePlayer()
    p.xp = 347
    expect(applyLevelUps(p).levelled).toBe(false)
    expect(p.level).toBe(1)

    p.xp = 348
    const r = applyLevelUps(p)
    expect(r.levelled).toBe(true)
    expect(p.level).toBe(2)
    // warrior primary str: +2; secondary stats +0; hp +10; mp +5
    expect(p.stats.str).toBe(12)
    expect(p.stats.def).toBe(8)
    expect(p.maxHp).toBe(160)
    expect(p.maxMp).toBe(35)
    expect(p.hp).toBe(160) // full heal
    expect(p.mp).toBe(35)
    expect(p.statPoints.unallocated).toBe(30)
    expect(r.msgs).toHaveLength(1)
    expect(r.msgs[0]).toContain('Level 2')
  })

  it('multi-level jump in one call', () => {
    const p = makePlayer()
    p.xp = levelsData.xpTable['5']! // 1812
    const r = applyLevelUps(p)
    expect(p.level).toBe(5)
    expect(r.msgs).toHaveLength(4)
    expect(p.stats.str).toBe(10 + 2 * 4)
    expect(p.maxHp).toBe(150 + 10 * 4)
    expect(p.statPoints.unallocated).toBe(15 * 5) // 75
  })

  it('never exceeds the level cap even with massive xp', () => {
    const p = makePlayer()
    p.xp = 99_999_999
    applyLevelUps(p)
    expect(p.level).toBe(levelsData.levelCap)
  })

  it('keeps allocations in baseStats across a level up', () => {
    const p = makePlayer()
    addAllocation(p, 'def', 7)
    p.xp = 348
    applyLevelUps(p)
    // base def = canonical lv2 def (8) + allocations (7)
    expect(p.baseStats.def).toBe(15)
    expect(p.stats.def).toBe(15)
  })
})

describe('ranks (bot parity)', () => {
  it.each([
    [1, 'E-Rank Hunter'],
    [15, 'D-Rank Hunter'],
    [42, 'A-Rank Hunter'],
    [100, 'Shadow Sovereign'],
  ])('level %i → %s', (level, title) => {
    expect(getRankForLevel(level).title).toBe(title)
  })

  it('covers every level 1..100 with no gaps', () => {
    for (let l = 1; l <= 100; l++) {
      const r = getRankForLevel(l)
      expect(l).toBeGreaterThanOrEqual(r.min)
      expect(l).toBeLessThanOrEqual(r.max)
    }
    expect(ranks[0].min).toBe(1)
    expect(ranks[ranks.length - 1].max).toBe(100)
  })

  it('next rank walks the ladder, null at the top', () => {
    expect(getNextRank(1)?.title).toBe('D-Rank Hunter')
    expect(getNextRank(100)).toBeNull()
  })
})

describe('getXpProgress (bot parity)', () => {
  it('level 1 floor is 0, next threshold xpTable[2]', () => {
    expect(getXpProgress(1, 0)).toEqual({
      pct: 0, intoLevel: 0, forLevel: 348, xpToNext: 348, maxed: false,
    })
  })

  it('level 5 at its own threshold is 0% in', () => {
    expect(getXpProgress(5, 1812)).toEqual({
      pct: 0, intoLevel: 0, forLevel: 704, xpToNext: 704, maxed: false,
    })
  })

  it('level 5 partway', () => {
    const p = getXpProgress(5, 2000)
    expect(p.intoLevel).toBe(188)
    expect(p.forLevel).toBe(704)
    expect(p.xpToNext).toBe(516)
    expect(p.pct).toBeCloseTo(0.26704545454545453, 12)
    expect(p.maxed).toBe(false)
  })

  it('at cap reads maxed', () => {
    expect(getXpProgress(100, 999999)).toEqual({
      pct: 1, intoLevel: 0, forLevel: 0, xpToNext: 0, maxed: true,
    })
  })
})
